<?php
$staff=is_staff($user);$id=(int)($_GET['id']??0);$edit=$staff&&(!empty($_GET['edit'])||!empty($_GET['new']));
$n=$id?one('SELECT * FROM news WHERE id=?'.($staff?'':' AND published=1'),[$id]):null;if($id&&!$n)throw new UserError(t('Neuigkeit nicht gefunden.','News not found.'));
page_head(t('Neuigkeiten','News'),t('Alle Informationen rund ums Training.','Updates about your training.'),$staff?link_button(t('+ Neuigkeit','+ Add news'),'news',['new'=>1]):'');
if($edit):?><section class="card"><?php start_form('news_save',['id'=>$id]);input('title',t('Titel','Title'),$n['title']??'','text',true);input('body',t('Inhalt','Content'),$n['body']??'','textarea',true);check_field('published',t('Im Portal veröffentlichen','Publish in the portal'),(bool)($n['published']??false));check_field('send_email',t('Diese Fassung zusätzlich an Newsletter-Abonnenten senden','Also email this version to newsletter subscribers'));submit_button();?></form></section>
<?php else:$list=$n?[$n]:rows('SELECT * FROM news'.($staff?'':' WHERE published=1').' ORDER BY updated_at DESC,id DESC');if(!$list)echo '<div class="card"><p class="muted">'.e(t('Noch keine Neuigkeiten.','No news yet.')).'</p></div>';foreach($list as $item):?><article class="card news-article"><div class="section-heading"><span class="eyebrow"><?=e(fmt_date($item['updated_at']))?></span><?php if(!$item['published'])badge(t('Entwurf','Draft'));?></div><h2><?=e($item['title'])?></h2><div class="prewrap"><?=e($item['body'])?></div><?php if($staff)echo link_button(t('Bearbeiten','Edit'),'news',['id'=>$item['id'],'edit'=>1],'secondary');?></article><?php endforeach;endif ?>
